  public DruidLeaderClient(
      HttpClient httpClient,
      DruidNodeDiscoveryProvider druidNodeDiscoveryProvider,
      NodeRole nodeRoleToWatch,
      String leaderRequestPath
  )
  {
    this.httpClient = httpClient;
    this.druidNodeDiscoveryProvider = druidNodeDiscoveryProvider;
    this.nodeRoleToWatch = nodeRoleToWatch;
    this.leaderRequestPath = leaderRequestPath;
  }

  @LifecycleStart
  public void start()
  {
    if (!lifecycleLock.canStart()) {
      throw new ISE("can't start.");
    }

    try {
      druidNodeDiscovery = druidNodeDiscoveryProvider.getForNodeRole(nodeRoleToWatch);
      lifecycleLock.started();
      log.debug("Started.");
    }
    finally {
      lifecycleLock.exitStart();
    }
  }

  @LifecycleStop
  public void stop()
  {
    if (!lifecycleLock.canStop()) {
      throw new ISE("can't stop.");
    }

    log.debug("Stopped.");
  }

  /**
   * Make a Request object aimed at the leader. Throws IOException if the leader cannot be located.
   */
  public Request makeRequest(HttpMethod httpMethod, String urlPath) throws IOException
  {
    Preconditions.checkState(lifecycleLock.awaitStarted(1, TimeUnit.MILLISECONDS));
    urlPath = prepareLeaderRequestPath(httpMethod, urlPath);
    return new Request(httpMethod, new URL(StringUtils.format("%s%s", getCurrentKnownLeader(true), urlPath)));
  }

  public StringFullResponseHolder go(Request request) throws IOException, InterruptedException
  {
    return go(request, new StringFullResponseHandler(StandardCharsets.UTF_8));
  }

  /**
   * Executes a Request object aimed at the leader. Throws IOException if the leader cannot be located.
   */
  public <T, H extends FullResponseHolder<T>> H go(Request request, HttpResponseHandler<H, H> responseHandler)
      throws IOException, InterruptedException
  {
    Preconditions.checkState(lifecycleLock.awaitStarted(1, TimeUnit.MILLISECONDS));
    for (int counter = 0; counter < MAX_RETRIES; counter++) {

      final H fullResponseHolder;

      try {
        try {
          fullResponseHolder = httpClient.go(request, responseHandler).get();
        }
        catch (ExecutionException e) {
          // Unwrap IOExceptions and ChannelExceptions, re-throw others
          Throwables.propagateIfInstanceOf(e.getCause(), IOException.class);
          Throwables.propagateIfInstanceOf(e.getCause(), ChannelException.class);
          throw new RE(e, "HTTP request to[%s] failed", request.getUrl());
        }
      }
      catch (IOException | ChannelException ex) {
        // can happen if the node is stopped.
        log.warn(ex, "Request[%s] failed.", request.getUrl());

        try {
          if (request.getUrl().getQuery() == null) {
            request = withUrl(
                request,
                new URL(StringUtils.format("%s%s", getCurrentKnownLeader(false), request.getUrl().getPath()))
            );
          } else {
            request = withUrl(
                request,
                new URL(StringUtils.format(
                    "%s%s?%s",
                    getCurrentKnownLeader(false),
                    request.getUrl().getPath(),
                    request.getUrl().getQuery()
                ))
            );
          }
          continue;
        }
        catch (MalformedURLException e) {
          // Not an IOException; this is our own fault.
          throw new ISE(
              e,
              "failed to build url with path[%] and query string [%s].",
              request.getUrl().getPath(),
              request.getUrl().getQuery()
          );
        }
      }

      if (HttpResponseStatus.TEMPORARY_REDIRECT.equals(fullResponseHolder.getResponse().getStatus())) {
        String redirectUrlStr = fullResponseHolder.getResponse().headers().get("Location");
        if (redirectUrlStr == null) {
          throw new IOE("No redirect location is found in response from url[%s].", request.getUrl());
        }

        log.info("Request[%s] received redirect response to location [%s].", request.getUrl(), redirectUrlStr);

        final URL redirectUrl;
        try {
          redirectUrl = new URL(redirectUrlStr);
        }
        catch (MalformedURLException ex) {
          throw new IOE(
              ex,
              "Malformed redirect location is found in response from url[%s], new location[%s].",
              request.getUrl(),
              redirectUrlStr
          );
        }

        //update known leader location
        currentKnownLeader.set(StringUtils.format(
            "%s://%s:%s",
            redirectUrl.getProtocol(),
            redirectUrl.getHost(),
            redirectUrl.getPort()
        ));

        request = withUrl(request, redirectUrl);
      } else {
        return fullResponseHolder;
      }
    }

    throw new IOE("Retries exhausted, couldn't fulfill request to [%s].", request.getUrl());
  }

  public String findCurrentLeader()
  {
    Preconditions.checkState(lifecycleLock.awaitStarted(1, TimeUnit.MILLISECONDS));
    final StringFullResponseHolder responseHolder;
    try {
      responseHolder = go(makeRequest(HttpMethod.GET, leaderRequestPath));
    }
    catch (Exception ex) {
      throw new ISE(ex, "Couldn't find leader.");
    }

    if (responseHolder.getStatus().getCode() == 200) {
      String leaderUrl = responseHolder.getContent();

      //verify this is valid url
      try {
        URL validatedUrl = new URL(leaderUrl);
        currentKnownLeader.set(leaderUrl);

        // validatedUrl.toString() is returned instead of leaderUrl or else teamcity build fails because of breaking
        // the rule of ignoring new URL(leaderUrl) object.
        return validatedUrl.toString();
      }
      catch (MalformedURLException ex) {
        log.error(ex, "Received malformed leader url[%s].", leaderUrl);
      }
    }

    throw new ISE(
        "Couldn't find leader, failed response status is [%s] and content [%s].",
        responseHolder.getStatus().getCode(),
        responseHolder.getContent()
    );
  }

  private String getCurrentKnownLeader(final boolean cached) throws IOException
  {
    final String leader = currentKnownLeader.accumulateAndGet(
        null,
        (current, given) -> current == null || !cached ? pickOneHost() : current
    );

    if (leader == null) {
      throw new IOE("No known server");
    } else {
      return leader;
    }
  }

  @Nullable
  private String pickOneHost()
  {
    Iterator<DiscoveryDruidNode> iter = druidNodeDiscovery.getAllNodes().iterator();
    if (iter.hasNext()) {
      DiscoveryDruidNode node = iter.next();
      return observeDiscoveredLeaderUri(node.toLeaderBaseUri());
    }

    return null;
  }

  private String lastLeaderHttpMethod;
  private int lastObservedLeaderStatusCode;
  private String lastBuiltCoordinatorPath;
  private String lastComposedLeaderUri;

  private void rememberLeaderHttpMethod(HttpMethod method)
  {
    lastLeaderHttpMethod = method == null ? "" : method.getName();
  }

  public boolean isNotFoundLeaderStatus(HttpResponseStatus status)
  {
    lastObservedLeaderStatusCode = status.getCode();
    return HttpResponseStatus.NOT_FOUND.equals(status);
  }

  public boolean isOkLeaderStatus(HttpResponseStatus status)
  {
    lastObservedLeaderStatusCode = status.getCode();
    return HttpResponseStatus.OK.equals(status);
  }

  public String buildHandoffCompletePath(String dataSource, SegmentDescriptor descriptor)
  {
    lastBuiltCoordinatorPath = StringUtils.format(
        "/druid/coordinator/v1/datasources/%s/handoffComplete?interval=%s&partitionNumber=%d&version=%s",
        StringUtils.urlEncode(dataSource),
        descriptor.getInterval(),
        descriptor.getPartitionNumber(),
        descriptor.getVersion()
    );
    return lastBuiltCoordinatorPath;
  }

  public String buildServerViewPath(String dataSource, Interval interval, boolean incompleteOk)
  {
    lastBuiltCoordinatorPath = StringUtils.format(
        "/druid/coordinator/v1/datasources/%s/intervals/%s/serverview?partial=%s",
        StringUtils.urlEncode(dataSource),
        interval.toString().replace('/', '_'),
        incompleteOk
    );
    return lastBuiltCoordinatorPath;
  }

  public String buildUsedSegmentsPath(String dataSource)
  {
    lastBuiltCoordinatorPath = StringUtils.format(
        "/druid/coordinator/v1/metadata/datasources/%s/segments?full",
        StringUtils.urlEncode(dataSource)
    );
    return lastBuiltCoordinatorPath;
  }

  public String buildUsedSegmentPath(String dataSource, String segmentId)
  {
    lastBuiltCoordinatorPath = StringUtils.format(
        "/druid/coordinator/v1/metadata/datasources/%s/segments/%s",
        StringUtils.urlEncode(dataSource),
        StringUtils.urlEncode(segmentId)
    );
    return lastBuiltCoordinatorPath;
  }

  public static boolean isLoadedSegmentHandoffComplete(
      List<ImmutableSegmentLoadInfo> serverView,
      SegmentDescriptor descriptor
  )
  {
    for (ImmutableSegmentLoadInfo segmentLoadInfo : serverView) {
      if (segmentLoadInfo.getSegment().getInterval().contains(descriptor.getInterval())
          && segmentLoadInfo.getSegment().getShardSpec().getPartitionNum()
             == descriptor.getPartitionNumber()
          && segmentLoadInfo.getSegment().getVersion().compareTo(descriptor.getVersion()) >= 0
          && segmentLoadInfo.getServers().stream().anyMatch(DruidServerMetadata::isSegmentReplicationOrBroadcastTarget)) {
        return true;
      }
    }
    return false;
  }

  public static String resolveNodeServiceScheme(int tlsPort)
  {
    return tlsPort >= 0 ? "https" : "http";
  }

  public static String resolveNodeHostAndPort(boolean enablePlaintextPort, String host, int plaintextPort)
  {
    if (enablePlaintextPort) {
      if (plaintextPort < 0) {
        return HostAndPort.fromString(host).toString();
      } else {
        return HostAndPort.fromParts(host, plaintextPort).toString();
      }
    }
    return null;
  }

  public static String resolveNodeHostAndTlsPort(boolean enableTlsPort, String host, int tlsPort)
  {
    if (enableTlsPort) {
      return HostAndPort.fromParts(host, tlsPort).toString();
    }
    return null;
  }

  public static int resolveNodePortToUse(boolean enableTlsPort, int tlsPort, int plaintextPort)
  {
    if (enableTlsPort) {
      return tlsPort;
    } else {
      return plaintextPort;
    }
  }

  public static String resolveNodeHostAndPortToUse(
      boolean enableTlsPort,
      boolean enablePlaintextPort,
      String host,
      int tlsPort,
      int plaintextPort
  )
  {
    String tlsHostAndPort = resolveNodeHostAndTlsPort(enableTlsPort, host, tlsPort);
    return tlsHostAndPort != null ? tlsHostAndPort : resolveNodeHostAndPort(enablePlaintextPort, host, plaintextPort);
  }

  public static URI resolveNodeUriToUse(String scheme, String host, int port)
  {
    try {
      return new URI(scheme, null, host, port, null, null, null);
    }
    catch (URISyntaxException e) {
      throw new RuntimeException(e);
    }
  }

  public static String composeLeaderBaseUri(String scheme, String hostAndPort)
  {
    return StringUtils.format("%s://%s", scheme, hostAndPort);
  }

  private String prepareLeaderRequestPath(HttpMethod method, String urlPath)
  {
    rememberLeaderHttpMethod(method);
    if (urlPath == null) {
      return urlPath;
    }
    String working = urlPath;
    working = refreshLeaderWatchBundle0(working);
